WITH ids AS (
    SELECT unnest(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[]) AS session_id
),
req_latest AS (
    SELECT DISTINCT ON (r.session_id) r.session_id, r.model
      FROM requests.requests r
     WHERE r.session_id = ANY(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[])
       AND r.model IS NOT NULL
     ORDER BY r.session_id, r.created_at DESC
),
req_counts AS (
    SELECT r.session_id, COUNT(*) AS request_count
      FROM requests.requests r
     WHERE r.session_id = ANY(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[])
     GROUP BY r.session_id
),
roster AS (
    SELECT DISTINCT ON (wr.session_id) wr.session_id, wr.cwd, wr.worktree
      FROM workspace.session_registrations wr
     WHERE wr.session_id = ANY(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[])
     ORDER BY wr.session_id, wr.registered_at DESC
),
goals AS (
    SELECT sg.session_id, sg.goal, sg.next_steps, sg.role
      FROM sessions.session_goals sg
     WHERE sg.session_id = ANY(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[])
),
subagent AS (
    SELECT DISTINCT ON (ai.session_id) ai.session_id, ag.name AS agent_type
      FROM agents.instances ai
      JOIN agents.agents ag ON ag.id = ai.agent_id
     WHERE ai.session_id = ANY(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[])
     ORDER BY ai.session_id, ai.created_at DESC
),
outcome AS (
    SELECT DISTINCT ON (v.session_id) v.session_id, o.code AS outcome
      FROM session_judges.verdicts v
      JOIN session_judges.outcomes o ON o.id = v.outcome_id
     WHERE v.session_id = ANY(ARRAY[484886,481438,481321,481409,481610,485774,481716,482208,481933,480448,480892,483929,482758,481561,480357,480813,480830,465969,479471,479620,479565,466256,478098,470452,454693,458034,465535,465136,458307,461086,461147,461121,458694,458703,458736,458717,456290,454995,454977,454862,454893,454162,437205,437611,440134,437270,443154,437500,443222,438125]::bigint[])
     ORDER BY v.session_id, v.judged_at DESC, v.id DESC
)
SELECT
    ids.session_id, rl.model, COALESCE(rc.request_count, 0) AS request_count,
    ro.cwd, ro.worktree, g.goal, g.next_steps, g.role AS declared_role, sa.agent_type,
    oc.outcome AS session_outcome
FROM ids
LEFT JOIN req_latest rl ON rl.session_id = ids.session_id
LEFT JOIN req_counts rc ON rc.session_id = ids.session_id
LEFT JOIN roster ro ON ro.session_id = ids.session_id
LEFT JOIN goals g ON g.session_id = ids.session_id
LEFT JOIN subagent sa ON sa.session_id = ids.session_id
LEFT JOIN outcome oc ON oc.session_id = ids.session_id;
